import React, { useState } from "react";
import axios from "axios";
import { ShieldAlert } from "lucide-react";

const ThreatLab = () => {
  const [status, setStatus] = useState(null);
  const [logs, setLogs] = useState([]);
  const [defense, setDefense] = useState(null);
  const [property, setProperty] = useState(null);

  const run = async (type) => {
    setLogs([]);
    setDefense(null);
    setProperty(null);
    setStatus("running");

    try {
      const res = await axios.post(
        "http://localhost:8000/simulate/attack?attack=" + type
      );

      // Show step animation
      if (res.data.steps) {
        let i = 0;
        const interval = setInterval(() => {
          if (i >= res.data.steps.length) {
            clearInterval(interval);
            setStatus(res.data.status);
            setDefense(res.data.defense);
            setProperty(res.data.property);
          } else {
            setLogs((prev) => [...prev, res.data.steps[i]]);
            i++;
          }
        }, 700);
      } else {
        setLogs([res.data.attack_info, res.data.detail]);
        setStatus(res.data.status);
        setDefense(res.data.defense);
        setProperty(res.data.property);
      }
    } catch (e) {
      setStatus("error");
    }
  };

  return (
    <div className="p-8 space-y-6">

      <h2 className="text-2xl font-bold text-white">
        Threat Simulation Lab
      </h2>

      {/* ATTACK BUTTONS */}
      <div className="flex flex-wrap gap-3">
        <button onClick={() => run("bitflip")} className="btn">Bit Flip</button>
        <button onClick={() => run("tag")} className="btn">Tag Corrupt</button>
        <button onClick={() => run("truncate")} className="btn">Truncate</button>
        <button onClick={() => run("mitm")} className="btn">MITM</button>
        <button onClick={() => run("cpa")} className="btn">CPA</button>
        <button onClick={() => run("cca")} className="btn">CCA</button>
      </div>

      {/* STATUS */}
      {status === "DETECTED" && (
        <div className="bg-red-500/20 border border-red-500 p-4 rounded animate-pulse">
          <ShieldAlert className="text-red-400"/>
          <p className="text-red-400 font-bold">TAMPER DETECTED</p>
        </div>
      )}

      {status === "FAILED" && (
        <div className="bg-yellow-500/20 border border-yellow-500 p-4 rounded">
          Tamper NOT detected
        </div>
      )}

      {status === "running" && (
        <div className="text-blue-400">Launching attack...</div>
      )}

      {/* LOGS */}
      <div className="bg-black/40 border border-gray-800 p-4 rounded text-xs font-mono text-green-400 space-y-1">
        {logs.map((l, i) => <p key={i}>[{i+1}] {l}</p>)}
      </div>

      {/* DEFENSE */}
      {defense && (
        <div className="text-xs text-cyan-400">
          <b>Defense Triggered:</b> {defense}
        </div>
      )}

      {/* PROPERTY */}
      {property && (
        <div className="text-xs text-yellow-400">
          <b>Security Property Preserved:</b> {property}
        </div>
      )}

    </div>
  );
};

export default ThreatLab;
